<?php
namespace App\Domain\Clients; use App\Domain\PublicChrome\PublicAssetPath; use App\Models\Client; use Illuminate\Support\Facades\Cache; use Throwable; final class ClientIndexViewData { public function get(int $page,?string $type=null,?int $industry=null):array{try{return Cache::remember('public.clients.index.v1.'.ClientCache::indexVersion().'.'.now()->format('YmdHi').".$page.$type.$industry",now()->addMinutes(10),fn()=>$this->load($page,$type,$industry));}catch(Throwable){return $this->load($page,$type,$industry);}} private function load(int $page,?string $type,?int $industry):array{$p=Client::publiclyVisible()->with('industry')->when($type,fn($q)=>$q->where('client_type',$type))->when($industry,fn($q)=>$q->where('industry_id',$industry))->orderByDesc('is_featured')->orderBy('display_order')->paginate(12,['*'],'page',$page);return ['items'=>$p->getCollection()->map(fn($x)=>['name'=>$x->name,'type'=>$x->client_type,'description'=>$x->short_description,'logo'=>PublicAssetPath::isSafe($x->logo_path)?$x->logo_path:null,'logo_alt'=>$x->logo_alt,'industry'=>$x->industry?->title,'url'=>route('clients.show',$x->slug)])->all(),'pagination'=>['current'=>$p->currentPage(),'last'=>$p->lastPage(),'previous'=>$p->previousPageUrl(),'next'=>$p->nextPageUrl()]];} }
